<template>
  <section class="reports">
    <div class="chart-controls"><h2>Dispatch reports</h2><Button label="Sync status" icon="pi pi-sync" severity="secondary" @click="tab='Syncs';loadSyncs()" /></div>
    <div class="filters">
      <label>From<InputText v-model="filters.dateFrom" type="date" /></label><label>To<InputText v-model="filters.dateTo" type="date" /></label>
      <label v-for="field in filterFields" :key="field.key">{{ field.label }}<Select v-model="filters[field.key]" :options="lookups[field.key]||[]" option-label="label" option-value="value" editable filter show-clear :placeholder="field.placeholder||'Select or type BC filter'" :virtualScrollerOptions="{itemSize:38}" /></label>
      <Button label="Apply filters" :loading="loading" @click="load" /><Button label="Clear" severity="secondary" @click="clearFilters" />
    </div>
    <p class="hint">BC filters: <code>JF*</code> starts with JF · <code>*beef*</code> contains beef · <code>B2235|B2240</code> either code · <code>B22??</code> two unknown characters. Plain text matches exactly; search dropdowns by code or name.</p>
    <Message v-if="error" severity="error">{{ error }}</Message>
    <Message severity="info" :closable="false">{{ reportNotice }} Reports load on demand, up to 31 days per request. Dropdown suggestions come from loaded results; you can also type codes or BC filters.</Message><p>Activity uses assembly/packing dates; the order list uses shipment dates. Assembly tonnage uses the latest revision of each line.</p>
    <div class="totals"><article><strong>{{ tonnes(packedKg) }} t</strong><span>Packed (closed boxes)</span></article><article><strong>{{ tonnes(assembledKg) }} t</strong><span>Assembled</span></article><article><strong>{{ sessions.length }}</strong><span>Sessions</span></article><article><strong>{{ pendingOrders }}</strong><span>Orders awaiting full packing</span></article></div>
    <Message v-if="missingKg" severity="warn">{{ missingKg }} assembly entries have no historical KG conversion and are excluded from tonnage.</Message>
    <div class="pipeline"><button v-for="stage in stages" :key="stage.label" @click="selectedStatus=selectedStatus===stage.key?'':stage.key;tab='Orders'" :class="{selected:selectedStatus===stage.key}"><strong>{{ stage.count }}</strong><span>{{ stage.label }}</span><progress :value="stage.count" :max="Math.max(orderCount,1)" /></button></div>
    <p v-if="selectedStatus">Order table: {{ selectedStatus }} <Button label="Show all statuses" text @click="selectedStatus=''" /></p>
    <h3>Tonnage by {{ groupBy.toLowerCase() }} <small>(top 20)</small></h3>
    <div class="chart-controls"><Select v-model="metric" :options="[{label:'Packed tonnage',value:'packing'},{label:'Assembly tonnage',value:'assembly'}]" option-label="label" option-value="value" /><Select v-model="groupBy" :options="['Operator','Day','Item']" /></div>
    <div class="chart" role="img" :aria-label="`${metric} tonnage by ${groupBy}`"><p v-if="!bars.length">No tonnage for the selected filters.</p><div v-for="bar in bars" :key="bar.label" class="bar-row"><span :title="bar.label">{{ bar.label }}</span><div class="bar-track"><div :style="{width:`${bar.percent}%`}" /></div><strong>{{ tonnes(bar.kg) }} t</strong></div></div>
    <nav class="tabs"><button v-for="v in ['Orders','Activity','Sessions','Claims','Syncs']" :key="v" :class="{active:tab===v}" @click="tab=v">{{ v }}</button><Button label="Export CSV" text icon="pi pi-download" @click="download" /></nav>
    <DataTable class="dispatch-report-table" v-if="tab==='Orders'" :value="tableRows.Orders" v-model:filters="tableFilters.Orders" filterDisplay="row" :globalFilterFields="tableFields.Orders" sortMode="multiple" removableSort @value-change="rows => visibleRows.Orders=rows" paginator :rows="25" scrollable size="small"><template #header><div class="table-search"><InputText v-model="tableFilters.Orders.global.value" placeholder="Search all columns" aria-label="Search Orders" /><Button label="Clear table filters" text @click="resetTableFilters('Orders')" /><small>Filter each column below. Click headers to sort; hold Ctrl/Command to sort by multiple columns.</small></div></template>
      <Column field="OrderNo" header="Order" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Orders','OrderNo')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'OrderNo'" @update:modelValue="filterCallback()" /></template></Column><Column field="Company" header="Company" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Orders','Company')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'Company'" @update:modelValue="filterCallback()" /></template></Column><Column field="CustomerLabel" header="Customer" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Orders','CustomerLabel')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'CustomerLabel'" @update:modelValue="filterCallback()" /></template><template #body="{data:r}">{{ r.CustomerNo }} - {{ r.CustomerName }}</template></Column><Column field="ShipmentDate" header="Shipment" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Orders','ShipmentDate')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'ShipmentDate'" @update:modelValue="filterCallback()" /></template></Column><Column field="Status" header="Status" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Orders','Status')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'Status'" @update:modelValue="filterCallback()" /></template></Column><Column field="ItemLabel" header="Item" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Orders','ItemLabel')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'ItemLabel'" @update:modelValue="filterCallback()" /></template><template #body="{data:r}">{{ r.ItemNo }} - {{ r.Description }}</template></Column><Column field="OrderQty" header="Ordered" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Orders','OrderQty')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'OrderQty'" @update:modelValue="filterCallback()" /></template></Column><Column field="AssembledQty" header="Assembled" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Orders','AssembledQty')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'AssembledQty'" @update:modelValue="filterCallback()" /></template></Column><Column field="PackedQty" header="Packed" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Orders','PackedQty')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'PackedQty'" @update:modelValue="filterCallback()" /></template></Column><Column field="Uom" header="UOM" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Orders','Uom')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'Uom'" @update:modelValue="filterCallback()" /></template></Column><Column field="RouteCode" header="Route" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Orders','RouteCode')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'RouteCode'" @update:modelValue="filterCallback()" /></template></Column><Column field="SalespersonName" header="Salesperson" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Orders','SalespersonName')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'SalespersonName'" @update:modelValue="filterCallback()" /></template></Column><Column field="ClaimedBy" header="Claimed by" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Orders','ClaimedBy')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'ClaimedBy'" @update:modelValue="filterCallback()" /></template></Column>
    </DataTable>
    <DataTable class="dispatch-report-table" v-if="tab==='Activity'" :value="tableRows.Activity" v-model:filters="tableFilters.Activity" filterDisplay="row" :globalFilterFields="tableFields.Activity" sortMode="multiple" removableSort @value-change="rows => visibleRows.Activity=rows" paginator :rows="25" scrollable size="small"><template #header><div class="table-search"><InputText v-model="tableFilters.Activity.global.value" placeholder="Search all columns" aria-label="Search Activity" /><Button label="Clear table filters" text @click="resetTableFilters('Activity')" /><small>Filter each column below. Click headers to sort; hold Ctrl/Command to sort by multiple columns.</small></div></template>
      <Column field="Stage" header="Stage" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Activity','Stage')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'Stage'" @update:modelValue="filterCallback()" /></template></Column><Column field="Status" header="Status" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Activity','Status')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'Status'" @update:modelValue="filterCallback()" /></template></Column><Column field="OrderNo" header="Order" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Activity','OrderNo')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'OrderNo'" @update:modelValue="filterCallback()" /></template></Column><Column field="ItemLabel" header="Item" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Activity','ItemLabel')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'ItemLabel'" @update:modelValue="filterCallback()" /></template><template #body="{data:r}">{{ r.ItemNo }} - {{ r.Description }}</template></Column><Column field="Quantity" header="Quantity" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Activity','Quantity')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'Quantity'" @update:modelValue="filterCallback()" /></template></Column><Column field="Uom" header="UOM" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Activity','Uom')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'Uom'" @update:modelValue="filterCallback()" /></template></Column><Column field="Pieces" header="Pieces" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Activity','Pieces')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'Pieces'" @update:modelValue="filterCallback()" /></template></Column><Column field="WeightKg" header="KG" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Activity','WeightKg')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'WeightKg'" @update:modelValue="filterCallback()" /></template></Column><Column field="BatchNo" header="Batch" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Activity','BatchNo')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'BatchNo'" @update:modelValue="filterCallback()" /></template></Column><Column field="Operator" header="Operator" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Activity','Operator')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'Operator'" @update:modelValue="filterCallback()" /></template></Column><Column field="ActivityAt" header="Time" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Activity','ActivityAt')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'ActivityAt'" @update:modelValue="filterCallback()" /></template><template #body="{data:r}">{{ time(r.ActivityAt) }}</template></Column>
    </DataTable>
    <div v-if="tab==='Sessions'" class="totals"><article v-for="summary in sessionRates" :key="summary.stage"><strong>{{ summary.stage }}: {{ rate(summary.weighted) }} kg/min</strong><span>Overall rate = summed KG / summed session minutes</span><span>Average session rate: {{ rate(summary.mean) }} kg/min</span></article></div>
    <p v-if="tab==='Sessions'">Dates select session start dates (Nairobi). Totals sum the KG of matching session entries, including open boxes, across the whole session. Missing KG is excluded; ongoing-session rates use elapsed time at refresh.</p>
    <DataTable class="dispatch-report-table" v-if="tab==='Sessions'" :value="tableRows.Sessions" v-model:filters="tableFilters.Sessions" filterDisplay="row" :globalFilterFields="tableFields.Sessions" sortMode="multiple" removableSort @value-change="rows => visibleRows.Sessions=rows" paginator :rows="25" scrollable size="small"><template #header><div class="table-search"><InputText v-model="tableFilters.Sessions.global.value" placeholder="Search all columns" aria-label="Search Sessions" /><Button label="Clear table filters" text @click="resetTableFilters('Sessions')" /><small>Filter each column below. Click headers to sort; hold Ctrl/Command to sort by multiple columns.</small></div></template>
      <Column field="Stage" header="Stage" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Sessions','Stage')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'Stage'" @update:modelValue="filterCallback()" /></template></Column><Column field="UserName" header="Operator" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Sessions','UserName')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'UserName'" @update:modelValue="filterCallback()" /></template></Column><Column field="WorkerCode" header="Worker code" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Sessions','WorkerCode')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'WorkerCode'" @update:modelValue="filterCallback()" /></template></Column><Column field="UserId" header="Worker / user ID" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Sessions','UserId')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'UserId'" @update:modelValue="filterCallback()" /></template></Column><Column field="ParentName" header="Main account" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Sessions','ParentName')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'ParentName'" @update:modelValue="filterCallback()" /></template></Column><Column field="CheckerName" header="Confirmer" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Sessions','CheckerName')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'CheckerName'" @update:modelValue="filterCallback()" /></template></Column><Column field="StartedAt" header="Started" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Sessions','StartedAt')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'StartedAt'" @update:modelValue="filterCallback()" /></template><template #body="{data:r}">{{ time(r.StartedAt) }}</template></Column><Column field="EndedAt" header="Ended" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Sessions','EndedAt')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'EndedAt'" @update:modelValue="filterCallback()" /></template><template #body="{data:r}">{{ r.EndedAt?time(r.EndedAt):'In progress' }}</template></Column><Column field="Minutes" header="Minutes" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Sessions','Minutes')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'Minutes'" @update:modelValue="filterCallback()" /></template><template #body="{data:r}">{{ (r.DurationSeconds/60).toFixed(1) }}</template></Column><Column field="WeightKg" header="KG" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Sessions','WeightKg')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'WeightKg'" @update:modelValue="filterCallback()" /></template><template #body="{data:r}">{{ rate(r.WeightKg) }}<small v-if="r.MissingKg"> ({{ r.MissingKg }} missing)</small></template></Column><Column field="Tonnes" header="Tonnes" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Sessions','Tonnes')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'Tonnes'" @update:modelValue="filterCallback()" /></template><template #body="{data:r}">{{ tonnes(r.WeightKg) }}</template></Column><Column field="KgPerMinute" header="KG/min" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Sessions','KgPerMinute')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'KgPerMinute'" @update:modelValue="filterCallback()" /></template><template #body="{data:r}">{{ rate(r.KgPerMinute) }}</template></Column><Column header="Details"><template #body="{data:r}"><Button label="View entries" text @click="openSession(r)" /></template></Column>
    </DataTable>
    <DataTable class="dispatch-report-table" v-if="tab==='Claims'" :value="tableRows.Claims" v-model:filters="tableFilters.Claims" filterDisplay="row" :globalFilterFields="tableFields.Claims" sortMode="multiple" removableSort @value-change="rows => visibleRows.Claims=rows" paginator :rows="25" scrollable size="small"><template #header><div class="table-search"><InputText v-model="tableFilters.Claims.global.value" placeholder="Search all columns" aria-label="Search Claims" /><Button label="Clear table filters" text @click="resetTableFilters('Claims')" /><small>Filter each column below. Click headers to sort; hold Ctrl/Command to sort by multiple columns.</small></div></template>
      <Column field="OrderNo" header="Order" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Claims','OrderNo')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'OrderNo'" @update:modelValue="filterCallback()" /></template></Column><Column field="Stage" header="Stage" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Claims','Stage')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'Stage'" @update:modelValue="filterCallback()" /></template></Column><Column field="UserName" header="Operator" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Claims','UserName')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'UserName'" @update:modelValue="filterCallback()" /></template></Column><Column field="ClaimedAt" header="Picked at" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Claims','ClaimedAt')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'ClaimedAt'" @update:modelValue="filterCallback()" /></template><template #body="{data:r}">{{ time(r.ClaimedAt) }}</template></Column><Column v-if="supervisor"><template #body="{data:r}"><Button label="Release claim" severity="warn" @click="release(r)" /></template></Column>
    </DataTable>
    <section v-if="tab==='Syncs'" class="sync-panel">
      <div><h3>Dispatch syncs</h3><Button label="Refresh status" :loading="syncLoading" @click="loadSyncs" /></div>
      <Message v-if="syncError" severity="error">{{ syncError }}</Message>
      <p>Status refreshes every 60 seconds while this tab is visible and online. Run history starts with this update; an unfinished run may indicate an interrupted server process.</p>
      <p v-if="syncCheckedAt">{{ syncCached ? 'Cached snapshot, not live' : 'Last checked' }}: {{ new Date(syncCheckedAt).toLocaleString() }}</p><div class="totals"><article v-for="u in syncData.units" :key="u.Company"><strong>{{ u.Company }}</strong><span>{{ u.CachedUnits }} cached item units</span><span>Refreshed {{ time(u.RefreshedAt) }}</span><span>{{ u.MissingKg }} missing KG conversions</span></article></div>
      <DataTable class="dispatch-report-table" :value="tableRows.Syncs" v-model:filters="tableFilters.Syncs" filterDisplay="row" :globalFilterFields="tableFields.Syncs" sortMode="multiple" removableSort @value-change="rows => visibleRows.Syncs=rows" paginator :rows="10" scrollable><template #header><div class="table-search"><InputText v-model="tableFilters.Syncs.global.value" placeholder="Search all columns" aria-label="Search Syncs" /><Button label="Clear table filters" text @click="resetTableFilters('Syncs')" /><small>Filter each column below. Click headers to sort; hold Ctrl/Command to sort by multiple columns.</small></div></template>
        <template #empty>No sync runs recorded yet.</template>
        <Column field="Kind" header="Sync" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Syncs','Kind')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'Kind'" @update:modelValue="filterCallback()" /></template></Column><Column field="status" header="Status" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Syncs','status')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'status'" @update:modelValue="filterCallback()" /></template></Column>
        <Column field="startedAt" header="Started" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Syncs','startedAt')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'startedAt'" @update:modelValue="filterCallback()" /></template><template #body="{data:r}">{{ time(r.startedAt) }}</template></Column>
        <Column field="endedAt" header="Finished" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Syncs','endedAt')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'endedAt'" @update:modelValue="filterCallback()" /></template><template #body="{data:r}">{{ r.endedAt?time(r.endedAt):'Not finished' }}</template></Column>
        <Column field="ResultText" header="Result" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Syncs','ResultText')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'ResultText'" @update:modelValue="filterCallback()" /></template><template #body="{data:r}">{{ syncSummary(r) }}</template></Column>
      </DataTable>
    </section>
    <Dialog v-model:visible="sessionVisible" modal class="dispatch-session-detail" header="Session entries" :style="{width:'74rem',maxWidth:'96vw'}">
      <p v-if="selectedSession">{{ selectedSession.Stage }} · {{ selectedSession.UserName }} · {{ time(selectedSession.StartedAt) }} · {{ rate(selectedSession.WeightKg) }} KG · {{ tonnes(selectedSession.WeightKg) }} t · {{ rate(selectedSession.KgPerMinute) }} kg/min</p>
      <DataTable class="dispatch-report-table" :value="tableRows.Entries" v-model:filters="tableFilters.Entries" filterDisplay="row" :globalFilterFields="tableFields.Entries" sortMode="multiple" removableSort @value-change="rows => visibleRows.Entries=rows" paginator :rows="15" scrollable size="small"><template #header><div class="table-search"><InputText v-model="tableFilters.Entries.global.value" placeholder="Search all columns" aria-label="Search Entries" /><Button label="Clear table filters" text @click="resetTableFilters('Entries')" /><small>Filter each column below. Click headers to sort; hold Ctrl/Command to sort by multiple columns.</small></div></template><Column field="OrderNo" header="Order" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Entries','OrderNo')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'OrderNo'" @update:modelValue="filterCallback()" /></template></Column><Column field="ItemNo" header="Item" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Entries','ItemNo')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'ItemNo'" @update:modelValue="filterCallback()" /></template></Column><Column field="Description" header="Description" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Entries','Description')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'Description'" @update:modelValue="filterCallback()" /></template></Column><Column field="Quantity" header="Quantity" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Entries','Quantity')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'Quantity'" @update:modelValue="filterCallback()" /></template></Column><Column field="Uom" header="UOM" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Entries','Uom')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'Uom'" @update:modelValue="filterCallback()" /></template></Column><Column field="Pieces" header="Pieces" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Entries','Pieces')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'Pieces'" @update:modelValue="filterCallback()" /></template></Column><Column field="WeightKg" header="KG" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Entries','WeightKg')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'WeightKg'" @update:modelValue="filterCallback()" /></template></Column><Column field="BatchNo" header="Batch" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Entries','BatchNo')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'BatchNo'" @update:modelValue="filterCallback()" /></template></Column><Column field="Status" header="Status" sortable :showFilterMenu="false"><template #filter="{filterModel,filterCallback}"><Select v-model="filterModel.value" :options="columnOptions('Entries','Status')" editable filter showClear :virtualScrollerOptions="{itemSize:38}" placeholder="Search or select" :aria-label="'Filter '+ 'Status'" @update:modelValue="filterCallback()" /></template></Column></DataTable>
    </Dialog>
  </section>
</template>
<script setup>
import '@/styles/dispatchSessionDetails.css'
import {readDispatchCache,writeDispatchCache} from '../../../shared/dispatchLocalCache.mjs'
import {ref,shallowRef,computed,onMounted,onUnmounted,watch} from 'vue'
import {dispatchApi} from '@/services/dispatch.js'
import {useAuthStore} from '@/stores/auth.js'
import InputText from 'primevue/inputtext'
import Button from 'primevue/button'
import Select from 'primevue/select'
import Message from 'primevue/message'
import DataTable from 'primevue/datatable'
import Column from 'primevue/column'
import Dialog from 'primevue/dialog'
import {sessionAverage} from '../../../shared/dispatchSessionMetrics.mjs'
const auth=useAuthStore(),supervisor=computed(()=>['admin','dispatch-supervisor'].includes(auth.effectiveRole))
const today=new Date(Date.now()+3*3600000).toISOString().slice(0,10),weekAgo=new Date(Date.now()+3*3600000-6*86400000).toISOString().slice(0,10)
const reportNotice=ref('Choose dates and apply filters to load reports.'),syncCheckedAt=ref(null),syncCached=ref(false)
const filters=ref({dateFrom:weekAgo,dateTo:today,item:'',customer:'',order:'',route:'',salesperson:'',operator:''}),data=shallowRef({activity:[],orders:[],sessions:[],claims:[]}),loading=ref(false),error=ref(''),tab=ref('Orders'),metric=ref('packing'),groupBy=ref('Operator')
const filterFields=[{key:'item',label:'Item code / name'},{key:'customer',label:'Customer number / name'},{key:'order',label:'Order number'},{key:'salesperson',label:'Salesperson'},{key:'route',label:'Route'},{key:'operator',label:'Packer / assembler'}]
const lookups=ref({}),applied=ref({}),selectedStatus=ref(''),syncData=ref({runs:[],units:[]}),syncLoading=ref(false),syncError=ref('')
const orderStatus=r=>['packed','loaded'].includes(r.Status)?'Packed':r.Status==='packing'?'Ongoing':'Pending'
const orderRows=computed(()=>data.value.orders.filter(r=>!selectedStatus.value||orderStatus(r)===selectedStatus.value))
const orderCount=computed(()=>new Set(data.value.orders.map(r=>r.DispatchOrderId)).size)
const stages=computed(()=>['Pending','Ongoing','Packed'].map(key=>({key,label:key==='Pending'?'Awaiting full packing':key==='Ongoing'?'Packing in progress':'Fully packed',count:new Set(data.value.orders.filter(r=>orderStatus(r)===key).map(r=>r.DispatchOrderId)).size})))
function syncSummary(r){if(r.error)return r.error;if(!r.result)return r.status==='running'?'Refresh in progress':'No result recorded';return Object.entries(r.result).map(([key,value])=>`${key}: ${Array.isArray(value)?value.join(', '):typeof value==='object'?JSON.stringify(value):value}`).join(' · ')}
function clearFilters(){for(const key of Object.keys(filters.value))filters.value[key]='';filters.value.dateFrom=weekAgo;filters.value.dateTo=today;selectedStatus.value=''}
async function loadSyncs(){if(syncLoading.value)return;syncLoading.value=true;syncError.value='';try{syncData.value=(await dispatchApi.syncStatus()).data;syncCheckedAt.value=Date.now();syncCached.value=false;writeDispatchCache(auth.user.userId,'syncSnapshot',{data:syncData.value,checkedAt:syncCheckedAt.value})}catch(e){syncError.value=e.response?.data?.error||e.message}finally{syncLoading.value=false}}
watch(tab,v=>{if(v==='Syncs')loadSyncs()})
const tonnes=kg=>(Number(kg||0)/1000).toLocaleString('en-KE',{maximumFractionDigits:4}),time=v=>new Date(v).toLocaleString('en-KE',{timeZone:'Africa/Nairobi'})
const packedKg=computed(()=>data.value.activity.filter(r=>r.Stage==='packing'&&r.Status==='packed').reduce((n,r)=>n+Number(r.WeightKg||0),0))
const assembledKg=computed(()=>data.value.activity.filter(r=>r.Stage==='assembly').reduce((n,r)=>n+Number(r.WeightKg||0),0))
const missingKg=computed(()=>data.value.activity.filter(r=>r.Stage==='assembly'&&r.WeightKg==null).length)
const pendingOrders=computed(()=>new Set(data.value.orders.filter(r=>!['packed','loaded'].includes(r.Status)).map(r=>r.DispatchOrderId)).size)
const sessions=computed(()=>data.value.sessions)
const sessionVisible=ref(false),selectedSession=ref(null)
const sessionEntries=computed(()=>(data.value.sessionEntries||[]).filter(e=>e.SessionId===selectedSession.value?.SessionId&&e.Stage===selectedSession.value?.Stage))
const sessionRates=computed(()=>['packing','assembly'].map(stage=>({stage,...sessionAverage(sessions.value.filter(s=>s.Stage===stage))})))
const rate=value=>value==null?'—':Number(value).toFixed(2)
function openSession(row){selectedSession.value=row;sessionVisible.value=true}
const bars=computed(()=>{const map=new Map(),names=new Map();for(const r of data.value.activity){if(r.Stage!==metric.value||(r.Stage==='packing'&&r.Status!=='packed')||r.WeightKg==null)continue;const key=groupBy.value==='Operator'?r.Operator:groupBy.value==='Item'?r.ItemNo:new Date(r.ActivityAt).toLocaleDateString('en-CA',{timeZone:'Africa/Nairobi'});if(groupBy.value==='Item'&&r.Description&&!names.has(key))names.set(key,r.Description);map.set(key,(map.get(key)||0)+Number(r.WeightKg))}const rows=[...map].map(([key,kg])=>({label:names.has(key)?`${key} - ${names.get(key)}`:key,kg})).sort((a,b)=>b.kg-a.kg).slice(0,20),max=Math.max(...rows.map(r=>r.kg),1);return rows.map(r=>({...r,percent:r.kg/max*100}))})
async function load(){if(loading.value)return;loading.value=true;error.value='';try{if(!filters.value.dateFrom||!filters.value.dateTo)throw new Error('Select both dates to limit mobile data usage');if((new Date(filters.value.dateTo)-new Date(filters.value.dateFrom))/86400000>30)throw new Error('Load up to 31 days at a time');if(filters.value.dateFrom&&filters.value.dateTo&&filters.value.dateFrom>filters.value.dateTo)throw new Error('Check the date range');const query={...filters.value};data.value=(await dispatchApi.reports(query)).data;applied.value=query;reportNotice.value='Loaded '+new Date().toLocaleString();writeDispatchCache(auth.user.userId,'reportFilters',query);const rows=[...data.value.orders,...data.value.activity];for(const [key,code,name] of [['item','ItemNo','Description'],['customer','CustomerNo','CustomerName'],['order','OrderNo','OrderNo'],['route','RouteCode','RouteCode'],['salesperson','SalespersonCode','SalespersonName'],['operator','Operator','Operator']]){const seen=new Map();for(const row of rows)if(row[code])seen.set(row[code],{value:row[code],label:row[code]===row[name]?row[code]:[row[code],row[name]].filter(Boolean).join(' - ')});lookups.value[key]=[...seen.values()]}}catch(e){error.value=e.response?.data?.error||e.message}finally{loading.value=false}}
async function release(row){try{await dispatchApi.releaseOrder(row.DispatchOrderId);await load()}catch(e){error.value=e.response?.data?.error||e.message}}

const tableFields={"Orders": ["OrderNo", "Company", "CustomerLabel", "ShipmentDate", "Status", "ItemLabel", "OrderQty", "AssembledQty", "PackedQty", "Uom", "RouteCode", "SalespersonName", "ClaimedBy"], "Activity": ["Stage", "Status", "OrderNo", "ItemLabel", "Quantity", "Uom", "Pieces", "WeightKg", "BatchNo", "Operator", "ActivityAt"], "Sessions": ["Stage", "UserName", "WorkerCode", "UserId", "ParentName", "CheckerName", "StartedAt", "EndedAt", "Minutes", "WeightKg", "Tonnes", "KgPerMinute"], "Claims": ["OrderNo", "Stage", "UserName", "ClaimedAt"], "Syncs": ["Kind", "status", "startedAt", "endedAt", "ResultText"], "Entries": ["OrderNo", "ItemNo", "Description", "Quantity", "Uom", "Pieces", "WeightKg", "BatchNo", "Status"]}
const makeTableFilters=key=>Object.fromEntries(['global',...tableFields[key]].map(field=>[field,{value:null,matchMode:'contains'}]))
const tableFilters=ref(Object.fromEntries(Object.keys(tableFields).map(key=>[key,makeTableFilters(key)]))),visibleRows=ref({})
function resetTableFilters(key){tableFilters.value[key]=makeTableFilters(key)}
const enrich=rows=>(rows||[]).map(r=>({...r,CustomerLabel:[r.CustomerNo,r.CustomerName].filter(Boolean).join(' - '),ItemLabel:[r.ItemNo,r.Description].filter(Boolean).join(' - '),Minutes:r.DurationSeconds==null?null:Number((r.DurationSeconds/60).toFixed(1)),ResultText:syncSummary(r)}))
const tableRows=computed(()=>({Orders:enrich(orderRows.value),Activity:enrich(data.value.activity),Sessions:enrich(sessions.value),Claims:enrich(data.value.claims),Syncs:enrich(syncData.value.runs),Entries:enrich(sessionEntries.value)}))
const tableOptions=computed(()=>{const result={};for(const key of new Set([tab.value,...(sessionVisible.value?['Entries']:[])])){result[key]={};for(const field of tableFields[key]||[])result[key][field]=[...new Set(tableRows.value[key].map(r=>r[field]).filter(v=>v!=null&&v!==''))].sort((a,b)=>typeof a==='number'&&typeof b==='number'?a-b:String(a).localeCompare(String(b),undefined,{numeric:true}))}return result})
function columnOptions(key,field){return tableOptions.value[key]?.[field]||[]}

function download(){const rows=visibleRows.value[tab.value]||tableRows.value[tab.value];if(!rows?.length)return;const keys=Object.keys(rows[0]),cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';const url=URL.createObjectURL(new Blob(['\uFEFF'+[keys,...rows.map(r=>keys.map(k=>r[k]))].map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`dispatch-${tab.value.toLowerCase()}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
let syncTimer
onMounted(()=>{const saved=readDispatchCache(auth.user.userId,'reportFilters');if(saved)filters.value={...filters.value,...saved.value};const sync=readDispatchCache(auth.user.userId,'syncSnapshot');if(sync){syncData.value=sync.value.data;syncCheckedAt.value=sync.value.checkedAt;syncCached.value=true}syncTimer=setInterval(()=>{if(tab.value==='Syncs'&&!document.hidden&&navigator.onLine)loadSyncs()},60000)})
onUnmounted(()=>clearInterval(syncTimer))
</script>
<style scoped>.table-search{display:flex;gap:.75rem;align-items:center;flex-wrap:wrap}.reports :deep(.p-datatable-filter .p-select){min-width:10rem;max-width:18rem}.pipeline{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(180px,100%),1fr));gap:1rem}.pipeline button{display:grid;gap:.6rem;padding:1rem;text-align:left;border:1px solid #0f766e;border-radius:10px;background:#134e4a;color:#ffffff;cursor:pointer}.pipeline strong{font-size:1.8rem}.pipeline button:hover{background:#115e59}.pipeline button:focus-visible,.pipeline .selected{outline:3px solid #2dd4bf;outline-offset:3px}.pipeline strong,.pipeline span{color:#ffffff}.pipeline progress{width:100%;accent-color:#5eead4}.sync-panel{display:grid;gap:1rem}.hint{font-size:.9rem}.reports{display:grid;grid-template-columns:minmax(0,1fr);gap:1rem;padding:1rem;min-width:0;max-width:100%;box-sizing:border-box}.reports>*{min-width:0}.sync-panel{grid-template-columns:minmax(0,1fr)}.dispatch-report-table{min-width:0;max-width:100%}.dispatch-report-table :deep(.p-datatable-table-container){max-width:100%;overflow-x:auto}.table-search>*{min-width:0;max-width:100%}.table-search small{overflow-wrap:anywhere}.filters label{min-width:0;max-width:100%}.filters :deep(.p-select){max-width:100%;min-width:0}.filters :deep(.p-select-label){min-width:0}.totals article,.pipeline button{min-width:0;overflow-wrap:anywhere}.filters,.chart-controls,.tabs{display:flex;flex-wrap:wrap;gap:.6rem;align-items:end}.filters label{display:grid;gap:.3rem}.totals{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(180px,100%),1fr));gap:1rem}.totals article{display:grid;gap:.5rem;padding:1rem;border:1px solid var(--p-content-border-color);border-radius:10px}.totals strong{font-size:1.6rem}.chart{display:grid;gap:.7rem;padding:1rem;border:1px solid var(--p-content-border-color);border-radius:10px}.bar-row{display:grid;grid-template-columns:minmax(0,180px) minmax(0,1fr) minmax(0,100px);gap:.5rem;align-items:center}.bar-row>span{overflow-wrap:anywhere}.bar-track{height:20px;background:var(--p-content-hover-background);border-radius:4px}.bar-track div{height:100%;background:var(--p-primary-color);border-radius:4px}.tabs button{padding:.8rem;border:0;background:transparent;color:inherit;cursor:pointer}.tabs button.active{border-bottom:3px solid var(--p-primary-color)}@media(max-width:640px){.bar-row{grid-template-columns:minmax(0,100px) minmax(0,1fr) minmax(0,75px);font-size:.8rem}.filters label{width:100%}}</style>
